/* NextPay email-signature logo assets — base64-inlined so generated signatures are self-contained.
   These are the PLATED logos: the full-color mark composited onto a baked-in white
   rounded background. Email clients never recolor image pixels, so the white backing
   travels with the logo and it stays visible on ANY background (incl. dark-mode Gmail). */
window.NP_SIG_ASSETS = {
  nextpay: "data:image/png;base64,",
  nextlink: "data:image/png;base64,"
};
